CREATE TABLE IF NOT EXISTS accounts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,password text NOT NULL,role text NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')));
CREATE TABLE IF NOT EXISTS sessions(token text PRIMARY KEY,user_id bigint NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS products(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,category text NOT NULL,description text NOT NULL,price integer NOT NULL CHECK(price>0),stock integer NOT NULL CHECK(stock>=0),image text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cart(user_id bigint REFERENCES accounts(id) ON DELETE CASCADE,product_id integer REFERENCES products(id),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS wishlist(user_id bigint REFERENCES accounts(id) ON DELETE CASCADE,product_id integer REFERENCES products(id),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id bigint REFERENCES accounts(id),created timestamptz DEFAULT now(),address text NOT NULL,total integer NOT NULL CHECK(total>=0),status text NOT NULL DEFAULT 'Placed' CHECK(status IN ('Placed','Processing','Shipped','Delivered')));
CREATE TABLE IF NOT EXISTS order_items(order_id bigint REFERENCES orders(id),product_id integer REFERENCES products(id),name text NOT NULL,price integer NOT NULL,quantity integer NOT NULL CHECK(quantity>0),PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS reviews(user_id bigint REFERENCES accounts(id),product_id integer REFERENCES products(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body text NOT NULL,created timestamptz DEFAULT now(),PRIMARY KEY(user_id,product_id));
